+				<td>' . htmlspecialchars($MyRow['userid'], ENT_QUOTES, 'UTF-8') . '</td>
+				<td>' . nl2br(htmlspecialchars($MyRow['note'], ENT_QUOTES, 'UTF-8')) . '</td>
+				<td><a href="' . $Link . 'Edit=' . $MyRow['noteid'] . '">' . __('Edit') . '</a></td>
+				<td><a href="' . $Link . 'Delete=' . $MyRow['noteid'] . '" onclick="return confirm(\'' . __('Are You Sure?') . '\');">' . __('Delete') . '</a></td>
+			</tr>';
+	}
+	echo '</table>';
+}
+
+$NoteText = '';
+if ($SelectedNote > 0) {
+	$Result = DB_query("SELECT note FROM stockitemnotes WHERE noteid=" . $SelectedNote . " AND stockid='" . $StockID . "'");
+	if (DB_num_rows($Result) == 1) {
+		$MyRow = DB_fetch_row($Result);
+		$NoteText = $MyRow[0];
+	} else {
+		$SelectedNote = 0;
+	}
+}
