+echo '<br /><form method="post" action="' . htmlspecialchars($_SERVER['PHP_SELF'], ENT_QUOTES, 'UTF-8') . '">
+		<input type="hidden" name="FormID" value="' . $_SESSION['FormID'] . '" />
+		<input type="hidden" name="StockID" value="' . $StockID . '" />
+		<input type="hidden" name="SelectedNote" value="' . $SelectedNote . '" />
+		<fieldset>
+			<legend>' . ($SelectedNote > 0 ? __('Edit Note') : __('Add a Note')) . '</legend>
+			<field>
+				<label for="Note">' . __('Note') . ':</label>
+				<textarea name="Note" id="Note" rows="5" cols="60" required="required">' . htmlspecialchars($NoteText, ENT_QUOTES, 'UTF-8') . '</textarea>
+			</field>
+		</fieldset>
+		<div class="centre">
+			<input type="submit" name="submit" value="' . __('Save') . '" />
+		</div>
+	</form>';
+
+include('includes/footer.php');
